import { liftedRowInks } from '@jbrowse/bandage-core/layout/rowInks'
import {
  placeRowGenes,
  rowSpan,
} from '@jbrowse/bandage-core/layout/walkRowDraw'
import { filterSamples } from '@jbrowse/bandage-core/layout/walkRows'
import {
  cutsWholeWalks as wholeWalksRule,
  stripMarks,
  walkStripApplies,
  walkStripFrame,
} from '@jbrowse/bandage-core/layout/walkStrip'
import { layoutModeByValue } from '@jbrowse/bandage-core/layoutModes'
import { passBars } from '@jbrowse/bandage-core/passBar'
import { nodeAnchor } from '@jbrowse/bandage-core/referenceStrip'

import { withLaunchViews } from './launchViews'
import { WALK_GENE_ROWS } from './paneBase'
import { resolveLocationAssembly } from '../../launchFromGraph/contributors'
import { measureReadout } from '../readoutMeasure'

import type { WalkAxis, WalkRow } from '@jbrowse/bandage-core/layout/walkRows'

export const withWalkRowViews = withLaunchViews
  .views(self => ({
    // Whether the strip of walk rows sits under the drawing: asked for, on a
    // standalone view whose layout draws nodes, for a graph with walks
    get walkStripShown() {
      return walkStripApplies({
        walkStrip: self.walkStrip,
        mode: { drawsNodes: self.modeDrawsNodes },
        drawsPicture: !!self.layoutResult?.tubeMap || !!self.walkRowBars,
        walks: self.graph?.paths?.length ?? 0,
        host: !!self.host,
      })
    },
    // The strip's rows: the cut's, with the sample filter and no repeat
    // pick, which the Repeat menu only offers in walk rows
    get walkStripRows() {
      const bars = this.walkStripShown ? self.cutWalkRows : undefined
      return bars
        ? { ...bars, rows: filterSamples(bars.rows, self.keptRowSamples) }
        : undefined
    },
    // The lifted walks' colours, which the strip's rows they name take
    get walkStripInks() {
      return liftedRowInks(self.drawnWalks)
    },
    // measured as the pane draws a readout, so the strip cuts one only where
    // it does not fit
    get walkStripFrame() {
      const bars = this.walkStripRows
      return bars
        ? {
            ...walkStripFrame(bars, { width: self.paneWidth }),
            measure: measureReadout,
          }
        : undefined
    },
    // Whether a cut must follow every snarl a walk leaves the window by, so
    // walks come back whole: walk rows measure them, and so does the strip
    // under a layout that draws nodes. Only a GBZ cut follows snarls; a walk
    // file cuts the same either way, so asking would re-fetch an identical
    // graph.
    get cutsWholeWalks() {
      const mode = layoutModeByValue(self.chosenLayoutMode)
      return (
        self.sourceAdapter?.type === 'GbzBaseSyntenyAdapter' &&
        wholeWalksRule(mode, {
          walkStrip: self.walkStrip && mode.drawsNodes,
          host: !!self.host,
        })
      )
    },
    // Where each walk passes the hovered node, or the selected one
    get walkStripMarks() {
      const bars = this.walkStripRows
      const id = self.hoveredNode ?? self.selectedNode
      const node = id === null ? undefined : self.nodeById?.get(id)
      return bars && node && self.graph
        ? stripMarks(self.graph, [bars.reference, ...bars.rows], node)
        : []
    },
    // Where a row's bar lies on its contig, and the session assembly its
    // haplotype (`HG00097#1`) or else its sample names
    rowLocation(row: WalkRow, axis: WalkAxis) {
      const named = {
        sample: row.sample,
        haplotype:
          row.haplotype === undefined
            ? undefined
            : `${row.sample}#${row.haplotype}`,
      }
      return {
        ...named,
        assembly: resolveLocationAssembly(self.assemblyResolver, named),
        span: { refName: axis.contig, ...rowSpan(axis, row.bp) },
      }
    },
    // The rows ribbons, shared blocks or the shared order compare, while one
    // of them is on
    get comparedRows() {
      return self.rowVisitsNeeded ? (self.walkRowBars?.rows ?? []) : []
    },
    // Each walk lifted by pass along its own length, under a drawing of
    // nodes in a view of its own, as bandage-core's figure stacks them, but
    // for a walk whose row the strip draws in its passes' colours; a faceted
    // pane names no pass
    get passBars() {
      return !self.host && self.drawsNodes && !self.facetPanels
        ? passBars(self.walkLift, this.walkStripRows)
        : []
    },
    // Where the drawing has the node a strip point lights, for the ring
    // that finds it in a hairball, unless the drawing folded it
    get walkStripLocator() {
      const id = self.stripHover ? self.hoveredNode : null
      return id === null || self.folded.has(id)
        ? undefined
        : nodeAnchor(self.nodePositions?.[id], self.toScreen)
    },
  }))
  .views(self => ({
    // The gene reads walk rows need, as the layout or the strip: for each row whose haplotype
    // (`HG00097#1`) names an assembly with a gene track, that track over the
    // span of its own contig the row's bar covers. The first WALK_GENE_ROWS
    // such rows are read, and the rest counted for the key.
    get walkGeneReads() {
      const bars = self.walkRowBars ?? self.walkStripRows
      if (!bars || !self.showGenes) {
        return undefined
      }
      const notDeleted = bars.rows.filter(row => !row.stepless)
      const reads = notDeleted.flatMap(row => {
        const location = row.axis ? self.rowLocation(row, row.axis) : undefined
        const assembly = location?.assembly
        const track = assembly
          ? self.geneTracksByAssembly.get(assembly)
          : undefined
        return location && assembly && track
          ? [
              {
                row: row.name,
                trackId: track.trackId,
                region: { assemblyName: assembly, ...location.span },
              },
            ]
          : []
      })
      const unplaced = notDeleted.filter(row => !row.axis).length
      return {
        reads: reads.slice(0, WALK_GENE_ROWS),
        gaps: {
          untracked: notDeleted.length - unplaced - reads.length,
          unplaced,
          unread: Math.max(0, reads.length - WALK_GENE_ROWS),
        },
      }
    },
    get walkRowGeneGaps() {
      return this.walkGeneReads?.gaps
    },
    // Where a walk row's bar lies in its own assembly, for a linear view to
    // open: the span of its contig the bar covers, on the session assembly
    // its haplotype names (the cut's own assembly for the reference row).
    // The label names the haplotype when no assembly is loaded for it.
    walkRowLaunchTarget(index: number, bars = self.walkRowBars) {
      const row = bars ? [bars.reference, ...bars.rows][index] : undefined
      if (!row?.axis) {
        return undefined
      }
      const { sample, haplotype, assembly, span } = self.rowLocation(
        row,
        row.axis,
      )
      return {
        label: row.label,
        assembly: index === 0 ? self.graphRegion?.assemblyName : assembly,
        location: { sample, haplotype, ...span },
      }
    },
    // Each row's genes as offsets along its bar: the reference row's from
    // the backbone's gene track while the backbone lies on that track's
    // assembly, every other row's from its own assembly
    get walkRowGenes() {
      const bars = self.walkRowBars ?? self.walkStripRows
      if (!bars || !self.showGenes) {
        return undefined
      }
      const byRow = new Map(self.walkGeneFeatures ?? [])
      if (self.geneFeatures && self.genesBindBackbone) {
        byRow.set(bars.reference.name, self.geneFeatures)
      }
      return byRow.size
        ? placeRowGenes([bars.reference, ...bars.rows], byRow)
        : undefined
    },
  }))
